// for forward compatibility.
//
// AgentRunnerService is served by coding-agent plugins (e.g. claude,
// opencode, codex). The daemon spawns one such plugin and routes session
// runs through it.
type AgentRunnerServiceServer interface {
	GetInfo(context.Context, *AgentRunnerServiceGetInfoRequest) (*AgentRunnerServiceGetInfoResponse, error)
	// Validate an explicit headless capability profile against the agent's
	// runtime operation surface without starting a run.
	PreflightHeadlessRun(context.Context, *PreflightHeadlessRunRequest) (*PreflightHeadlessRunResponse, error)
	// Spawn the agent in work_dir with plan piped to stdin. log_path is
	// bossd-owned (under the daemon's data dir, NOT the worktree); the
	// plugin opens it with openat(O_NOFOLLOW) and writes one NDJSON line
	// per output line: {"ts": "...", "text": "..."}. resume_id (optional)
	// makes the agent resume that session. session_id is an optional requested
	// ID; the plugin may generate its own. The caller must use the returned
	// session ID for subsequent run operations.
	StartAgentRun(context.Context, *StartAgentRunRequest) (*StartAgentRunResponse, error)
	// Send SIGTERM (then SIGKILL after WaitDelay) to the named run.
	// Legacy name: retain the existing request and response wire names.
	// buf:lint:ignore RPC_REQUEST_STANDARD_NAME
	// buf:lint:ignore RPC_RESPONSE_STANDARD_NAME
	StopRun(context.Context, *StopAgentRunRequest) (*StopAgentRunResponse, error)
	// Liveness check.
	// Legacy name: retain the existing request and response wire names.
	// buf:lint:ignore RPC_REQUEST_STANDARD_NAME
	// buf:lint:ignore RPC_RESPONSE_STANDARD_NAME
	IsRunning(context.Context, *IsAgentRunningRequest) (*IsAgentRunningResponse, error)
	// Final exit status. exit_error is empty on clean exit. is_complete
	// is false if the run is still active.
	// Legacy name: retain the existing request and response wire names.
	// buf:lint:ignore RPC_REQUEST_STANDARD_NAME
	// buf:lint:ignore RPC_RESPONSE_STANDARD_NAME
	ExitStatus(context.Context, *AgentExitStatusRequest) (*AgentExitStatusResponse, error)
	// Configure the agent's "tell bossd when the run finishes" hook. For
	// Claude this writes .claude/settings.local.json. Returns
	// is_supported=false for agents without one.
	ConfigureFinalizeHook(context.Context, *ConfigureFinalizeHookRequest) (*ConfigureFinalizeHookResponse, error)
	// Remove the run-scoped Stop-hook entry a prior ConfigureFinalizeHook (with
	// a non-empty agent_session_id) installed. Called by the daemon when a run
	// completes so a finished run's completion ping can't linger in the
	// worktree's settings.local.json. No-op (is_supported may be false) for
	// agents without a finalize hook. Idempotent: removing an absent entry
	// succeeds.
	RemoveAgentRunHook(context.Context, *RemoveAgentRunHookRequest) (*RemoveAgentRunHookResponse, error)
	// Build the argv for an interactive (tmux-hosted) launch. bossd captures
	// stdout/stderr to log_path with tmux pipe-pane; argv MUST NOT tee output.
	BuildInteractiveCommand(context.Context, *BuildInteractiveCommandRequest) (*BuildInteractiveCommandResponse, error)
	// ResolveInteractiveSessionID discovers the provider-owned session ID for an
	// interactive tmux launch. Agents that accept caller-provided IDs may return
	// requested_session_id. Agents like Codex scan their transcript store.
	ResolveInteractiveSessionID(context.Context, *ResolveInteractiveSessionIDRequest) (*ResolveInteractiveSessionIDResponse, error)
	// Files in workDir that the agent owns (e.g. .claude/settings.local.json).
	// bossd unions these into git-status filtering.
	ListIgnoredDirtyFiles(context.Context, *ListIgnoredDirtyFilesRequest) (*ListIgnoredDirtyFilesResponse, error)
	// Title from the agent's transcript for a given run.
	GetChatTitle(context.Context, *GetChatTitleRequest) (*GetChatTitleResponse, error)
	// SuggestPRTitle asks the agent to propose a concise pull-request title from
	// the git history + PR description, returning the current title UNCHANGED when
	// it already describes the change accurately. The daemon uses this at cron
	// finalize instead of deriving the title from the last commit subject.
	// supported=false (or any error) means "agent has no opinion" — the daemon
	// then falls back to its deterministic title heuristic, so plugins that do not
	// implement this stay correct.
	SuggestPRTitle(context.Context, *SuggestPRTitleRequest) (*SuggestPRTitleResponse, error)
	// HasQuestionPrompt scans pane content for the agent's TUI grammar that
	// signals "waiting for the user to answer a question." Plugin owns its
	// grammar; daemon owns the timing logic that combines this with content-
	// change detection.
	HasQuestionPrompt(context.Context, *HasQuestionPromptRequest) (*HasQuestionPromptResponse, error)
	// HasWorkingIndicator scans pane content for the agent's TUI grammar that
	// signals "still actively working" (e.g. a running background shell or an
	// active spinner), even when the pane is otherwise static. Plugin owns its
	// grammar; the daemon uses it to keep a busy-but-static pane from flipping
	// idle. Consulted only in the would-be-idle branch, so active chats pay no
	// extra RPC.
	HasWorkingIndicator(context.Context, *HasWorkingIndicatorRequest) (*HasWorkingIndicatorResponse, error)
	// LastTurnIsUser reports whether the most recent meaningful turn in the
	// agent's transcript is a user message (not a tool-result-only entry).
	// Used to suppress the QUESTION status when the user has already replied.
	LastTurnIsUser(context.Context, *LastTurnIsUserRequest) (*LastTurnIsUserResponse, error)
	// DetectUsageLimit scans pane content for the agent's usage-cap banner in
	// the CLI-owned status region below the bottom-most prompt marker. Plugin
	// owns the per-agent banner grammar; the daemon owns the LIMITED status
	// transition and reset-time plumbing. Fail-safe: no status-region match =>
	// limited=false. reset_at is absent when no reset time is parseable.
	DetectUsageLimit(context.Context, *DetectUsageLimitRequest) (*DetectUsageLimitResponse, error)
	// ProbeRateLimit authoritatively reports the target account's usage-cap
	// posture by querying the provider directly (claude: GET /api/oauth/usage;
	// codex: the rollout JSONL under CODEX_HOME) rather than scraping the TUI.
	// credential_env carries that account's materialized env overlay so bossd can
	// probe ANY account on demand; it is secret-bearing and NEVER logged.
	// Providers without a probe return status=RATE_LIMIT_PLAN_STATUS_UNSUPPORTED,
	// limited=false (fail-safe).
	ProbeRateLimit(context.Context, *ProbeRateLimitRequest) (*ProbeRateLimitResponse, error)
	// TranscriptExists reports whether a non-empty transcript file is present
	// on disk for (work_dir, agent_session_id). Used by wake-up logic to
	// choose between resume and fresh-start argv.
	TranscriptExists(context.Context, *TranscriptExistsRequest) (*TranscriptExistsResponse, error)
	// ReadTranscript parses the agent's on-disk transcript for a chat and returns
	// its messages plus the derived final assistant message. Each plugin resolves
	// the transcript path the same way it does for TranscriptExists.
	ReadTranscript(context.Context, *ReadTranscriptRequest) (*ReadTranscriptResponse, error)
	// ProbeProgressLiveness reports when the agent last made SEMANTIC progress on
	// a chat (a new transcript record) and which phase that record leaves the
	// agent in. It exists because pane content is not a progress signal: an
	// animated spinner keeps changing while the turn behind it is dead, so the
	// daemon's content-change comparison reads a hung run as "working". Each
	// plugin resolves the transcript path the same way it does for
	// TranscriptExists and reads only the tail.
	//
	// Fail open: a plugin that does not implement this (codes.Unimplemented), or
	// that cannot read its transcript, returns is_known=false and the daemon raises
	// NOTHING. A false "your session is dead" banner on a healthy long build is
	// worse than the silent stall this detects.
	ProbeProgressLiveness(context.Context, *ProbeProgressLivenessRequest) (*ProbeProgressLivenessResponse, error)
	// RotationCapability reports whether this agent supports account rotation and,
	// if so, how its credentials are injected (an env token like
	// CLAUDE_CODE_OAUTH_TOKEN, or a per-account home dir like CODEX_HOME). Agents
	// that do not implement it (codes.Unimplemented) degrade to status-only:
	// supports_rotation=false, never an error.
	RotationCapability(context.Context, *RotationCapabilityRequest) (*RotationCapabilityResponse, error)
	// MaterializeAccount turns an opaque, provider-specific credential blob into a
	// concrete process-credential spec: an environment overlay (e.g.
	// CLAUDE_CODE_OAUTH_TOKEN) and/or home-dir files (e.g. codex auth.json) plus
	// the env key that must point at that home dir (home_dir_env_key, e.g.
	// CODEX_HOME). Only the owning plugin ever sees its provider's blob. The blob
	// and all returned secret material are NEVER logged.
	//
	// codex note: the returned home-dir spec assumes a BASE-SEEDED codex home —
	// the per-account dir must have its sessions/ (and session_index.jsonl) shared
	// or symlinked from a shared base home, with only auth.json written fresh.
	// BOS-158 proved a per-account home whose sessions/ lacks the rollout fails
	// fast (thread/resume: no rollout found ... code -32600). Seeding sessions/ is
	// BOS-162's credmaterialize executor's job, NOT this RPC's; MaterializeAccount
	// returns only auth.json + HomeDirEnvKey=CODEX_HOME. See
	// docs/solutions/account-rotation/spike-cross-account-resume-credential-isolation.md.
	MaterializeAccount(context.Context, *MaterializeAccountRequest) (*MaterializeAccountResponse, error)
	// DescribeMCPSurface reports the MCP servers the agent ACTUALLY resolves for a
	// chat's worktree under the supplied environment, plus each server's tool
	// inventory and the tool-name prefix skills must call. Read-only apart from
	// applying its project_trust decision (as a launch of the chat would): it
	// never starts a coding turn.
	//
	// Fail-honest, never fail-guessing: a plugin that cannot answer returns
	// codes.Unimplemented; a probe that ran but failed returns a populated
	// probe_error with servers empty. "No servers" and "could not ask" are
	// deliberately distinguishable.
	DescribeMCPSurface(context.Context, *DescribeMCPSurfaceRequest) (*DescribeMCPSurfaceResponse, error)
	mustEmbedUnimplementedAgentRunnerServiceServer()
}

